describe('Language Preference Setting in Profile Settings', () => {
  beforeEach(() => {
    cy.visit('/profile');
  });

  it('should successfully set language preference and save it to profile', () => {
    // Verify initial language is default
    cy.get('[data-testid="language-dropdown"]').should('be.visible');
    cy.get('[data-testid="language-dropdown"]').should('contain', 'English');

    // Intercept API call to save language preference
    cy.intercept('POST', '/api/user/profile/settings/language').as('setLanguage');

    // Click on the dropdown and select a new language
    cy.get('[data-testid="language-dropdown"]').click();
    cy.get('[data-testid="language-option"]').click({ force: true });
    cy.get('[data-testid="language-option"]').should('contain', 'Spanish');

    // Verify language was updated in UI
    cy.get('[data-testid="language-dropdown"]').should('contain', 'Spanish');

    // Verify API call was made
    cy.wait('@setLanguage').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify language preference is saved
    cy.get('[data-testid="language-preference"]').should('contain', 'Español');
  });

  it('should handle invalid language input and show error message', () => {
    // Verify initial language is default
    cy.get('[data-testid="language-dropdown"]').should('be.visible');
    cy.get('[data-testid="language-dropdown"]').should('contain', 'English');

    // Intercept API call to save language preference
    cy.intercept('POST', '/api/user/profile/settings/language').as('setLanguage');

    // Click on the dropdown and select an invalid language
    cy.get('[data-testid="language-dropdown"]').click();
    cy.get('[data-testid="language-option"]').click({ force: true });
    cy.get('[data-testid="language-option"]').type('InvalidLanguage');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid language selected');

    // Verify dropdown still shows valid options
    cy.get('[data-testid="language-dropdown"]').should('contain', 'English');

    // Verify API call was not made
    cy.wait('@setLanguage').then((interception) => {
      expect(interception.request.body.language).to.not.equal('InvalidLanguage');
    });
  });
});
